// Loads the JS-oracle expectations next to the markdown tests
// (test/markdown/*.json, regenerated by test/markdown/tool/regen_js_cases.js).

import 'dart:convert' show jsonDecode;
import 'dart:io' show Directory, File, Platform;

/// Reads `test/markdown/<name>` from the package, whatever the test's cwd.
List<Map<String, dynamic>> markdownDataCases(String name) {
  final sep = Platform.pathSeparator;
  var dir = Directory.current;
  for (;;) {
    final candidate = File('${dir.path}${sep}test${sep}markdown$sep$name');
    if (candidate.existsSync()) {
      final value = jsonDecode(candidate.readAsStringSync());
      if (value is! List) throw StateError('$name must be a JSON array');
      return [for (final c in value) c as Map<String, dynamic>];
    }
    final parent = dir.parent;
    if (parent.path == dir.path) {
      throw StateError('test/markdown/$name not found from cwd');
    }
    dir = parent;
  }
}
